PARENT = ('Outsourced Cyber Security', '/outsourced-cyber')


def svc(slug, name, **kw):
    d = dict(kind='service', slug=slug, service_name=name, card_kind='Cyber security service', card_title=name,
             eyebrow='Outsourced Cyber Security', trail=[PARENT, (name, '/' + slug)])
    d.update(kw)
    return d


